library(ggplot2)
library(parallel)
p &lt;- load_hiv_params()             # params/hiv.csv + the shared Vietnamese inputs
n_cores &lt;- detectCores()
n_workers &lt;- min(4, max(1, n_cores - 1))   # leave one core for the operating system
N_REP &lt;- 3000                               # people per replication
N_TASKS &lt;- 8                                # number of independent replications
N_CHECK &lt;- 10000                            # people in the R-versus-C++ check and benchmark
N_PSA_PEOPLE &lt;- 1000                        # people per run in the PSA cost estimate
N_PSA_RUNS &lt;- 2000                          # runs in a PSA: 1,000 parameter sets x 2 strategies
POP_BLOCK &lt;- 100000                         # seeds for the populations: 100001, 100002, ...
SIM_BLOCK &lt;- 200000                         # seeds for the events:      200001, 200002, ...
task_ids &lt;- seq_len(N_TASKS)
c(cores = n_cores, workers = n_workers)

