Máy chạy bài này có 12 lõi; ta dùng 4 worker. parLapply() nhanh hơn 3.5 lần, còn mclapply() nhanh hơn 3.8 lần. PSOCK chậm hơn fork một chút vì phải khởi động các phiên R mới và nạp lại mã.
Tiếp theo là Rcpp. Bước biên dịch chỉ chạy một lần mỗi phiên R. Nếu máy chưa có trình biên dịch hoạt động, đoạn mã không dừng mà đặt has_cpp bằng FALSE, và các phần C++ bên dưới được bỏ qua.

# Compile the C++ kernel once per session (a few seconds). Without a working compiler the
# lesson goes on without the C++ parts instead of stopping.
t_compile &lt;- NA_real_
has_cpp &lt;- tryCatch({
  t_compile &lt;- system.time(compile_microsim_cpp())[["elapsed"]]
  TRUE
}, error = function(e) {
  message("C++ compilation failed: ", conditionMessage(e))
  FALSE
})
c(has_cpp = has_cpp, compile_seconds = round(t_compile, 1))

        has_cpp compile_seconds 
            1.0             1.8 


Biên dịch mất 1.8 giây. Toàn bộ mã C++ nằm trong code/microsim.cpp; hãy đặt nó cạnh run_microsim() ở Bài 3 và dò ba bước.


Xem code/microsim.cpp
// M04 microsimulation kernel in C++ (Rcpp). Same algorithm as run_microsim() in
// code/model.R, written as plain loops: cycles outside, people inside.
// Random numbers: in every cycle, n uniforms (one per person) -- the same order as
// runif(n) in R, so the same seed gives the same individuals. One uniform decides
// death, change of viral state or acquired resistance (competing risks).
// Compile with compile_microsim_cpp().
// License: MIT.
#include &lt;Rcpp.h&gt;
using namespace Rcpp;

// [[Rcpp::export]]
List microsim_cpp(NumericVector age0, NumericVector adh, List p,
                  double int_first, double int_after, int n_cycles,
                  NumericVector disc_start, NumericVector disc_mid, NumericVector disc_end,
                  NumericVector v_cost_tx, NumericVector v_cost_vir,
                  NumericVector v_util, NumericVector v_alive) {
  const int n = age0.size();
  // Life table (lower bound of each age group, annual death rate), as in bg_mortality()
  NumericVector lt_age = p["lt_age"], lt_mx = p["lt_mx"];
  const int n_lt = lt_age.size();
  const double mu_supp = p["mu_supp"], mu_vir = p["mu_vir"], vir_slope = p["vir_slope"];
  const double r_reb1 = p["r_reb1"], r_reb2 = p["r_reb2"], hr_adh10 = p["hr_adh10"];
  const double r_resup1 = p["r_resup1"], r_resup2 = p["r_resup2"], hr_eac = p["hr_eac"];
  const double r_adr = p["r_adr"];
  const double eac_months = p["eac_months"], c_vl = p["c_vl"];
  const double eac_sessions = p["eac_sessions"], c_visit_unit = p["c_visit_unit"];
  const double c_eac = eac_sessions * c_visit_unit;   // same product as sim_setup() in R

  // Attributes that change over time (the model's memory) and accumulators
  IntegerVector state(n, 1);
  NumericVector res(n), cum_vir(n), eac(n), next_test(n, int_first);
  LogicalVector ever_flag(n), switched(n), unnecessary(n);
  NumericVector cost(n), qaly(n), ly(n), ly_undisc(n), n_vl(n), n_eac(n), n_rep1(n);
  IntegerMatrix trace(n_cycles + 1, 5);
  IntegerVector f1_res(n_cycles + 1);
  NumericVector u(n);
  trace(0, 0) = n;

  for (int t = 1; t &lt;= n_cycles; t++) {
    for (int i = 0; i &lt; n; i++) u[i] = R::runif(0.0, 1.0);
    const double ds = disc_start[t - 1], dm = disc_mid[t - 1], de = disc_end[t - 1];

    for (int i = 0; i &lt; n; i++) {
      int s = state[i];
      if (s == 5) { trace(t, 4) += 1; continue; }

      // 1. One event at most: death, change of viral state, or acquired resistance
      const double age = age0[i] + (t - 1) / 12.0;
      int g = n_lt - 1;                                  // age group: largest lower bound &lt;= age
      while (g &gt; 0 && age &lt; lt_age[g]) g--;
      const bool viremic = (s == 2 || s == 4);
      const double mu_hiv = (viremic ? mu_vir : mu_supp) * (1 + vir_slope * cum_vir[i] / 12);
      const double death = (lt_mx[g] + mu_hiv) / 12;
      const double boost = eac[i] &gt; 0 ? hr_eac : 1.0;
      double move;
      if (s == 1)      move = r_reb1 * R_pow(hr_adh10, 10 * (1 - adh[i]));
      else if (s == 2) move = (1 - res[i]) * r_resup1 * adh[i] * boost;
      else if (s == 3) move = r_reb2 * R_pow(hr_adh10, 10 * (1 - adh[i]));
      else             move = r_resup2 * adh[i] * boost;
      move = move / 12;
      const double adr = ((s == 2 && res[i] == 0) ? r_adr : 0.0) / 12;
      const double total = death + move + adr;
      const double p_exit = 1 - exp(-total);
      const double p_die = death / total * p_exit;
      const double p_move = move / total * p_exit;
      const double p_adr = adr / total * p_exit;
      int ns = s;
      if (u[i] &lt; p_die) ns = 5;
      else if (u[i] &lt; p_die + p_move) ns = (s == 1) ? 2 : (s == 2) ? 1 : (s == 3) ? 4 : 3;
      else if (u[i] &lt; p_die + p_move + p_adr) res[i] = 1;   // stays in F1, now resistant

      // 2. Rewards; state values are indexed 0..4 in C++
      cost[i] = cost[i] + v_cost_tx[s - 1] * ds +
        (v_cost_vir[s - 1] + v_cost_vir[ns - 1]) / 2 * dm;
      qaly[i] = qaly[i] + (v_util[s - 1] + v_util[ns - 1]) / 2 / 12 * dm;
      const double ly_t = (v_alive[s - 1] + v_alive[ns - 1]) / 2 / 12;
      ly[i] = ly[i] + ly_t * dm;
      ly_undisc[i] = ly_undisc[i] + ly_t;
      cum_vir[i] = cum_vir[i] + (viremic ? 1 : 0);
      s = ns;

      // 3. Monitoring at the end of the cycle
      if (s != 5) {
        bool tested = false, detected = false;
        if (eac[i] &gt; 0) {
          eac[i] = eac[i] - 1;
          if (eac[i] == 0) {
            tested = true;
            if (s == 1 || s == 2) n_rep1[i] = n_rep1[i] + 1;
            if (s == 2) {
              s = 4;
              switched[i] = true;
              if (res[i] == 0) unnecessary[i] = true;
            }
            next_test[i] = t + int_after;
          }
        } else if (t &gt;= next_test[i]) {
          tested = true;
          if (s == 2 || s == 4) {
            detected = true;
            eac[i] = eac_months;
            ever_flag[i] = true;
          } else {
            next_test[i] = t + (ever_flag[i] ? int_after : int_first);
          }
        }
        n_vl[i] = n_vl[i] + (tested ? 1 : 0);
        n_eac[i] = n_eac[i] + (detected ? 1 : 0);
        cost[i] = cost[i] + ((tested ? 1.0 : 0.0) * c_vl + (detected ? 1.0 : 0.0) * c_eac) * de;
      }
      state[i] = s;
      trace(t, s - 1) += 1;
      if (s == 2 && res[i] == 1) f1_res[t] += 1;
    }
  }

  return List::create(_["cost"] = cost, _["qaly"] = qaly, _["ly"] = ly,
                      _["ly_undisc"] = ly_undisc, _["months_vir"] = cum_vir,
                      _["res"] = res, _["switched"] = switched,
                      _["unnecessary"] = unnecessary, _["n_vl"] = n_vl,
                      _["n_eac"] = n_eac, _["n_rep1"] = n_rep1,
                      _["trace"] = trace, _["f1_res"] = f1_res);
}


Khi có trình biên dịch, kiểm tra quan trọng nhất là: cùng 10,000 người, cùng seed, R và C++ phải cho kết quả giống hệt nhau.

