sim_r &lt;- run_microsim(p, pop_10k, "vl12", seed = 52)
if (has_cpp) {
  sim_c &lt;- run_microsim_cpp(p, pop_10k, "vl12", seed = 52)
  stopifnot(identical(sim_r$indiv, sim_c$indiv), identical(sim_r$trace, sim_c$trace),
            identical(sim_r$f1_res, sim_c$f1_res))
  "R và C++ cho cùng lịch sử sống của từng người"
}

